-- Round 4: a messy set of accounts left behind by "the previous admin".
-- DO NOT EDIT THIS FILE. The grader always uses the instructor's copy.
-- bootstrap.sh runs it as root, after schema.sql and load.sql, and then runs your fixes.sql.
-- It starts by dropping these accounts, so it is safe to run again and again.

DROP USER IF EXISTS
  's6705142016_webapp'@'%', 's6705142016_webapp'@'localhost',
  's6705142016_kiosk'@'localhost', 's6705142016_kiosk'@'%',
  's6705142016_intern'@'%', 's6705142016_intern'@'localhost',
  's6705142016_etl'@'localhost', 's6705142016_etl'@'%',
  's6705142016_report'@'localhost', 's6705142016_report'@'%';

CREATE USER 's6705142016_webapp'@'%' IDENTIFIED BY 'Webapp#2026';
GRANT ALL PRIVILEGES ON *.* TO 's6705142016_webapp'@'%' WITH GRANT OPTION;

CREATE USER 's6705142016_kiosk'@'localhost' IDENTIFIED BY '';
GRANT SELECT ON reg_6705142016.students TO 's6705142016_kiosk'@'localhost';

CREATE USER 's6705142016_intern'@'%' IDENTIFIED BY 'Intern#2025';
GRANT SELECT, INSERT, UPDATE ON reg_6705142016.* TO 's6705142016_intern'@'%';

CREATE USER 's6705142016_etl'@'localhost' IDENTIFIED BY 'Etl#2026';
GRANT FILE ON *.* TO 's6705142016_etl'@'localhost';
GRANT INSERT ON reg_6705142016.enrollments TO 's6705142016_etl'@'localhost';

CREATE USER 's6705142016_report'@'localhost' IDENTIFIED BY 'Report#2026';
GRANT SELECT, INSERT, UPDATE, DELETE ON reg_6705142016.* TO 's6705142016_report'@'localhost';
